import{_ as r,l as o,o as l,c as s,v as d,p as E,x as t,d as i,i as p,S as A,b as a}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"深度对宽度","description":"","frontmatter":{"title":"深度对宽度","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/depth-vs-width.md","filePath":"llm/depth-vs-width.md","lastUpdated":1789023840000}'),B={name:"llm/depth-vs-width.md"};function h(c,e,m,u,N,f){const n=o("Mermaid");return l(),s("div",null,[e[1]||(e[1]=d('<h1 id="深度对宽度" tabindex="-1">深度对宽度 <a class="header-anchor" href="#深度对宽度" aria-label="Permalink to &quot;深度对宽度&quot;">​</a></h1><div class="epigraph"><p>同样参数量可以堆成更深更窄或更浅更宽；损失对这两轴并不对称，过深会先碰到优化墙，过浅会先碰到表示墙。</p><footer>—— Kaplan et al., Scaling Laws for Neural Language Models, 2020；深度效率见 Tay et al., Scale Efficiently, ICLR 2022</footer></div><p><a href="/llm/silent-data-corruption-training">上一课</a>收束稳定性。本课打开缩放实践单元：形状怎么选。主干 <a href="/llm/kaplan-scaling">Kaplan</a> 把损失写成 \\(N,D,C\\) 的幂律，其中 \\(N\\) 是参数量，并不自动告诉你 \\(N\\) 该拆成层数 \\(L\\) 还是宽度 \\(d\\)。GPT-3 一类用「深且宽」的经验比例；Tay 等人指出许多「更大」其实是把计算浪费在不增深度效率的轴上。本课只补 \\(L\\) vs \\(d\\)，词表大小下一课才进 \\(N\\) 的账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数量粗算 \\(N\\approx 12 L d^2\\)（解码器，忽略词表）。固定 \\(N\\)，加 \\(L\\) 必须减 \\(d\\)。深度加的是串行残差步数、可组合的回路；宽度加的是每步的通道与注意力头的容量。Kaplan 观察到，在合理范围内深度与宽度可以交换且损失相近，但离开带子——极深极窄或极浅极宽——损失变差。优化墙：极深即使 Pre-LN，仍有 <a href="/llm/activation-scale-drift">激活漂移</a> 与注意力熵塌缩。表示墙：极浅即使很宽，层数不够形成多步算法（induction 一类回路需要深度方向的组合）。</p><p>FLOPs 近似 \\(C\\approx 6ND\\) 对固定 \\(N\\) 几乎不区分形状，但<strong>墙钟</strong>区分：深度阻碍流水线气泡与并行度，宽度利好 GEMM。计算最优（Chinchilla）给的是 \\(N\\)，不是形状。部署侧宽度还决定 KV 与 GEMM 形状。选形状是稳定性、并行与表示三约束，不是只最小化 \\(N\\)。</p><p><span class="marginnote">把 \\(N\\) 相同的两个模型叫「同样大小」会掩盖词表参数。\\(|V|d\\) 在窄模型里占比更大。比较 \\(L\\) vs \\(d\\) 时应声明 \\(N\\) 是否含嵌入，否则窄模型被词表支配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经验带子（须在你的配方上复测，不是物理常数）：\\(d/L\\) 过大则浅宽，\\(d/L\\) 过小则深窄。GPT-3 70B 量级用 80 层与数千宽度，落在带子里。改形状的消融应：</p><ol><li>固定 token 数与 \\(\\eta\\) 日程类型（μP 若只迁宽度，深度改变要重扫或用深度缩放）。</li><li>固定 \\(N_{\\mathrm{non\\text{-}embed}}\\) 再扫 \\(L\\)。</li><li>看幂律段斜率与最终 CE，同时看注意力熵与顶层 RMS——深窄模型更容易先触发稳定性单元里的传感器。</li></ol><p>Tay 等人的 Scale Efficiently 提醒：加宽、加头、加窗口，有的增加 FLOPs 却几乎不降损失。深度相对这些「假宽度」往往更值钱，直到优化墙。不要把能跑满 GPU 的最宽模型自动当成最优形状。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>回路形成需要层间组合：Olsson 等人的 induction 是跨层的。宽度增加的是并行特征数，不能替代那几步串行。反之，每层容量太小（\\(d\\) 太小、头太少），注意力没有足够的子空间同时做多种路由。带子就是这两种瓶颈尚未主导的区间。稳定性把带子的深端切掉：没有 QK-Norm / cap / 深度缩放时，可用 \\(L\\) 比理论表示需要的 \\(L\\) 更小。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MoE 把「有效 \\(N\\)」与「每 token FLOPs」拆开，形状课的 \\(12Ld^2\\) 不再够用，升级 MoE 课再谈。本课不管词表；\\(|V|\\) 下一课单独进缩放律。也不把「更深总是更好」写成定律——过深的墙是优化与通信，不是表示理论不喜欢深度。</p><p>μP 只迁宽度时，改 \\(L\\) 必须回到深度缩放与代理应力，不能把宽模型上扫到的 \\(\\eta\\) 原样贴到加了 20 层的同宽网上。深度改变之后，注意力熵与顶层 RMS 的报警阈值也要按新的 \\(L\\) 重标定，而不是沿用浅网的分位数。</p>',16)),(l(),E(A,null,{default:t(()=>[p(n,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%9B%BA%E5%AE%9A%E9%9D%9E%E5%B5%8C%E5%85%A5%E5%8F%82%E6%95%B0%20N%22%5D%20--%3E%20L%5B%22%E5%8A%A0%E6%B7%B1%E5%BA%A6%E5%87%8F%E5%AE%BD%E5%BA%A6%22%5D%0A%20%20N%20--%3E%20D%5B%22%E5%8A%A0%E5%AE%BD%E5%BA%A6%E5%87%8F%E6%B7%B1%E5%BA%A6%22%5D%0A%20%20L%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E5%A2%99%EF%BC%9A%E6%BC%82%E7%A7%BB%E4%B8%8E%E7%86%B5%E5%A1%8C%E7%BC%A9%22%5D%0A%20%20D%20--%3E%20REP%5B%22%E8%A1%A8%E7%A4%BA%E5%A2%99%EF%BC%9A%E5%9B%9E%E8%B7%AF%E5%B1%82%E6%95%B0%E4%B8%8D%E5%A4%9F%22%5D%0A%20%20BAND%5B%22%E7%BB%8F%E9%AA%8C%E5%B8%A6%E5%AD%90%22%5D%20--%3E%20N%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a("h2",{id:"小结",tabindex:"-1"},[i("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[3]||(e[3]=a("ul",null,[a("li",null,"\\(N\\) 固定时 \\(L\\) 与 \\(d\\) 可交换，但只在一条带子内；两端分别是优化墙与表示墙。"),a("li",null,"FLOPs 公式看不见形状；墙钟、KV、稳定性看得见。"),a("li",null,"比较形状时用非嵌入 \\(N\\)，并固定 token 与稳定件。"),a("li",null,"假宽度（加 FLOPs 不降损失）不如把预算留给深度，直到传感器报警。"),a("li",null,"改深度后 μP 的 \\(\\eta\\) 不能原样贴；带宽子与稳定件要一起重测。"),a("li",null,"出处：Kaplan et al., 2020；Tay et al., ICLR 2022。")],-1))])}const C=r(B,[["render",h]]);export{P as __pageData,C as default};
